/* Wave70 _4 independent source role/frame corrections; host only. */
.pgd-host-reference .pgd-roster{padding:0;border-radius:0;background:transparent;box-shadow:none}.pgd-host-reference .pgd-roster-heading{padding:0 4px;margin-bottom:8px}.pgd-host-reference .pgd-roster-heading>view>view{font-size:11px;line-height:14px;font-weight:700;letter-spacing:.22px}.pgd-host-reference .pgd-member-grid{padding:12px;border-radius:12px;background:#fff;box-shadow:0 1px 2px 0 rgba(0,0,0,.05)}.pgd-host-reference .pgd-roster-empty{padding:12px;border-radius:12px;background:#fff;box-shadow:0 1px 2px 0 rgba(0,0,0,.05)}.pgd-host-reference .pgd-roster>.pgd-help{background:transparent}
.pgd-host-reference .pgd-host-state>view>view:last-child>text:first-child{color:#424655}.pgd-host-reference .pgd-hero-title{color:#fff}
.pgd-host-reference .pgd-map-frame{box-shadow:inset 0 2px 4px rgba(0,0,0,.05)}.pgd-host-reference .pgd-map-frame:after{content:"";position:absolute;inset:0;border-radius:8px;pointer-events:none;box-shadow:inset 0 2px 4px rgba(0,0,0,.05)}.pgd-host-reference .pgd-terminal{margin-top:8px}
.pgd-host-reference .pd-members .pgd-host-capacity{display:flex;align-items:baseline;gap:4px;color:#424655;font-weight:600}.pgd-host-reference .pgd-host-capacity .pgd-capacity-number{font-size:17px;line-height:22px;letter-spacing:-.17px;font-weight:800;color:#004cc8}.pgd-host-reference .pgd-host-capacity .pgd-capacity-denominator{font-size:17px;line-height:22px;letter-spacing:-.17px;font-weight:600;color:#424655}.pgd-host-reference .pgd-host-capacity .pgd-capacity-unit{font-size:11px;line-height:14px;letter-spacing:.22px;font-weight:700;color:#424655}
